+HB_INTERNAL inline
+void single_subst_closure (hb_closure_context_t *c,
+                           const Coverage &coverage,
+                           hb_codepoint_t d, hb_codepoint_t mask)
+{
+  /* Help fuzzer avoid this function as much. */
+  unsigned pop = coverage.get_population ();
+  if (pop >= mask)
