+      for (auto feature_index : feature_indexes)
+      {
+        auto feature_ptr = fv.find_substitute (i, feature_index);
+        if (feature_ptr != nullptr)
+          feature_ptr->add_lookup_indexes_to (&lookup_indexes);
+      }
