+static void
+_append_arg (hb_vector_t<char> &sb, const char *arg)
+{
+  if (sb.in_error ()) return;
+  if (sb.length)
+    sb.push (' ');
+  unsigned len = strlen (arg);
+  sb.extend (hb_bytes_t (arg, len));
